<script lang="ts">
 import {validateReconstruction,reconstructionScene,footprintBounds} from '$lib/home/reconstruction.js';
 let {model}=$props<{model:any}>();let level=$state('');let selected=$state('');let mode=$state('2D');let focused=$state(false);let turn=$state(0);
 let parsed=$derived.by(()=>{try{return validateReconstruction(model);}catch{return null;}});
 $effect(()=>{if(parsed&&!parsed.levels.some(l=>l.id===level))level=parsed.levels[0].id;});
 let floor=$derived(level||parsed?.levels[0]?.id||'');let rooms=$derived(parsed?.rooms.filter(r=>r.level===floor)??[]);let room=$derived(rooms.find(r=>r.id===selected));
 let bounds=$derived(footprintBounds((focused&&room)?room.polygon:rooms.flatMap(r=>r.polygon),3));
 let scene=$derived.by(()=>{try{return reconstructionScene(model,floor,turn);}catch{return null;}});
 const points=(p:number[][])=>p.map(v=>v.join(',')).join(' ');
 const center=(p:number[][])=>[p.reduce((n,v)=>n+v[0],0)/p.length,p.reduce((n,v)=>n+v[1],0)/p.length];
</script>
<section><h2>Blueprint reconstruction</h2>{#if parsed}<p><strong>Source-derived draft · dimensions need review</strong></p><p>These outlines preserve source geometry and each room’s recorded construction status. Traced outlines may differ from written dimensions. Floor elevations, wall thicknesses and openings are not established by these footprints.</p>
 <label>Floor <select bind:value={level} onchange={()=>{selected='';focused=false;}}>{#each parsed.levels as l}<option value={l.id}>{l.id}</option>{/each}</select></label><label>Room <select value={selected} onchange={e=>selected=e.currentTarget.value}><option value="">Choose a room</option>{#each rooms as r}<option value={r.id}>{r.name}</option>{/each}</select></label><button onclick={()=>{mode='2D';focused=true;}} disabled={!room}>Focus selected room</button><button onclick={()=>focused=false}>Show whole floor</button><button aria-pressed={mode==='2D'} onclick={()=>mode='2D'}>2D footprints</button><button aria-pressed={mode==='3D'} onclick={()=>mode='3D'}>3D footprint illustration</button>
 <p>Orientation: {parsed.coordinateFrame.x} / {parsed.coordinateFrame.y}. North: {parsed.coordinateFrame.north}.</p>
 {#if mode==='2D'}<svg viewBox={`${bounds.x} ${bounds.y} ${bounds.w} ${bounds.h}`} role="group" aria-label="Source-derived room footprints">{#each rooms as r}<polygon points={points(r.polygon)} fill={r.id===selected?'#d9eee4':'#f5f8f6'} stroke="#647a70" stroke-width="0.15" role="button" tabindex="0" aria-label={`Inspect ${r.name}`} onclick={()=>selected=r.id} onkeydown={e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();selected=r.id;}}}/><text x={center(r.polygon)[0]} y={center(r.polygon)[1]} text-anchor="middle" font-size="1">{r.name}</text>{/each}</svg>
 {:else}<p>Depth is illustrative only. This is not a physical 3D building or a stack of floor elevations.</p><button onclick={()=>turn=(turn+3)%4}>Rotate left</button><button onclick={()=>turn=(turn+1)%4}>Rotate right</button><button onclick={()=>turn=0}>Reset orientation</button>{#if scene}<svg viewBox={`${scene.bounds.x} ${scene.bounds.y} ${scene.bounds.w} ${scene.bounds.h}`} role="group" aria-label="Illustrated blueprint footprints">{#each scene.rooms as r}{#each r.top as p,i}<polygon points={points([p,r.top[(i+1)%r.top.length],r.bottom[(i+1)%r.top.length],r.bottom[i]])} fill="#b9c8bf" stroke="#647a70" stroke-width="0.1"/>{/each}<polygon points={points(r.top)} fill={r.id===selected?'#d9eee4':'#f5f8f6'} stroke="#647a70" stroke-width="0.15" role="button" tabindex="0" aria-label={`Inspect ${r.name} illustration`} onclick={()=>selected=r.id} onkeydown={e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();selected=r.id;}}}/><text x={r.label[0]} y={r.label[1]} text-anchor="middle" font-size="1">{r.name}</text>{/each}</svg>{/if}{/if}
 {#if room}<article><h3>{room.name}</h3><p>Sheet {room.sourceSheet}, PDF page {room.sourcePage}. {room.geometryStatus}; {room.constructionStatus}.</p><p>Source-recorded height: {room.heightFeet===null?'unknown':`${room.heightFeet.toFixed(2)} ft (not used for illustrative depth)`}.</p></article>{/if}
 <details><summary>Evidence and limitations</summary><p>Source: {parsed.source.file}</p>{#each parsed.limitations as note}<p>{note}</p>{/each}</details>
 {:else}<p>The reconstruction could not be displayed. Its saved evidence remains unchanged; the maintainer needs to check the geometry format.</p>{/if}</section>
<style>section{margin:30px 0}h2{font-size:25px}p{line-height:1.6}svg{width:100%;height:500px;border:1px solid #b6cbbd;border-radius:12px;background:white;margin:20px 0}polygon[role=button]{cursor:pointer}text{pointer-events:none;fill:#263f32}select,button{background:white;padding:10px 16px;border:1px solid #cadbd1;border-radius:8px;color:#254a3c;margin:8px}article{padding:16px;background:#edf5ef;border-radius:8px}</style>
